import{d as g,C as r,o as h,c as d,j as i,a as e,E as a,a3 as m}from"./chunks/framework.Q4yG9rk_.js";const b=JSON.parse('{"title":"中庸·第20章","description":"《中庸》第 20 章——哀公问政：为政在人、取人以身；仁义与礼所生；五达道三达德；九经；诚者天之道，为学五步与「人一能之己百之」。","frontmatter":{"title":"中庸·第20章","description":"《中庸》第 20 章——哀公问政：为政在人、取人以身；仁义与礼所生；五达道三达德；九经；诚者天之道，为学五步与「人一能之己百之」。","category":"guide","aliases":["第20章","中庸第20章","哀公问政"],"source":["《礼记》","《四书章句集注》"],"outline":[2,3]},"headers":[],"relativePath":"lizhimingde/sishu-wujing/zhongyong/chapter-20.md","filePath":"lizhimingde/sishu-wujing/zhongyong/chapter-20.md","lastUpdated":1790316338000}'),u={name:"lizhimingde/sishu-wujing/zhongyong/chapter-20.md"},z=g({...u,setup(p){const o=[{id:"weizheng",label:"哀公问政 · 为政在人，取人以身",showLabel:!0,sentences:[["哀公问政。子曰：“文武之政，布在",{text:"方策",glossary:"fangce"},"。其人存，则其政举；其人亡，则其政息。人道",{text:"敏政",glossary:"minzheng"},"，地道敏树。夫政也者，",{text:"蒲卢",glossary:"pulu"},"也。故为政在人，取人以身，修身以道，修道以仁。"]],note:"鲁哀公问政。孔子说：文王、武王的政事都记载在方策（典籍）上，然而「其人存，则其政举；其人亡，则其政息」——有那样的人在，政就推行；人不在，政也就止息。以「人道敏政，地道敏树」作比（敏＝速），又说「夫政也者，蒲卢也」（蒲卢，蒲苇，易生之物）。归结为「为政在人，取人以身，修身以道，修道以仁」——全章之纲，层层递推。"},{id:"renyi",label:"仁者人也 · 亲亲之杀，尊贤之等 · 不可以不知天",showLabel:!0,sentences:[["仁者人也，亲亲为大；义者宜也，尊贤为大；亲亲之",{text:"杀",glossary:"shai"},"，尊贤之等，礼所生也。在下位不获乎上，民不可得而治矣！故君子不可以不修身；思修身，不可以不事亲；思事亲，不可以不知人；思知人，不可以不知天。”"]],note:"「仁者人也，亲亲为大；义者宜也，尊贤为大」——仁即人之所以为人，以亲爱亲人为大；义即合宜，以尊崇贤者为大。由「亲亲之杀（等差）、尊贤之等」而礼由此生。又逆推一层：「故君子不可以不修身；思修身，不可以不事亲；思事亲，不可以不知人；思知人，不可以不知天。」"},{id:"dadao",label:"五达道 · 三达德 · 好学力行知耻",showLabel:!0,sentences:[["天下之",{text:"达道",glossary:"dadao"},"五，所以行之者三：曰君臣也，父子也，夫妇也，昆弟也，朋友之交也：五者天下之达道也。知、仁、勇三者，天下之",{text:"达德",glossary:"dade"},"也，所以行之者一也。或生而知之，或学而知之，或困而知之，及其知之一也；或安而行之，或利而行之，或勉强而行之，及其成功一也。"],["子曰：“好学近乎知，力行近乎仁，知耻近乎勇。知斯三者，则知所以修身；知所以修身，则知所以治人；知所以治人，则知所以治天下国家矣。”"]],note:"「天下之达道五」：君臣、父子、夫妇、昆弟、朋友之交——五者是人共由之道。「所以行之者三」：知、仁、勇——三者是天下通行之德（达德）；「所以行之者一也」（一，即诚）。又「或生而知之，或学而知之，或困而知之，及其知之一也」，以及安行、利行、勉强而行，「及其成功一也」。下文孔子续说：「好学近乎知，力行近乎仁，知耻近乎勇」——知此三者，则知所以修身、治人、治天下国家。"},{id:"jiujing",label:"凡为天下国家有九经",showLabel:!0,sentences:[["凡为天下国家有",{text:"九经",glossary:"jiujing"},"，曰：修身也，尊贤也，亲亲也，敬大臣也，体群臣也，子庶民也，来百工也，柔远人也，怀诸侯也。修身则道立，尊贤则不惑，亲亲则诸父昆弟不怨，敬大臣则不",{text:"眩",glossary:"xuan"},"，体群臣则士之报礼重，子庶民则百姓",{text:"劝",glossary:"quan"},"，来百工则财用足，柔远人则四方归之，怀诸侯则天下畏之。"]],note:"「凡为天下国家有九经」（经＝常道）：修身、尊贤、亲亲、敬大臣、体群臣、子庶民、来百工、柔远人、怀诸侯。随即列九者的效验：修身则道立，尊贤则不惑，亲亲则诸父昆弟不怨，敬大臣则不眩，体群臣则士之报礼重，子庶民则百姓劝，来百工则财用足，柔远人则四方归之，怀诸侯则天下畏之。"},{id:"jiujingmu",label:"九经之目 · 所以行之者一也",showLabel:!0,sentences:[["齐明盛服，非礼不动，所以修身也；去谗远色，贱货而贵德，所以劝贤也；尊其位，重其禄，同其好恶，所以劝亲亲也；官盛任使，所以劝大臣也；忠信重禄，所以劝士也；时使薄敛，所以劝百姓也；日省月试，既",{text:"禀称事",glossary:"linchen"},"，所以劝百工也；送往迎来，嘉善而矜不能，所以柔远人也；继绝世，举废国，治乱持危，朝聘以时，厚往而薄来，所以怀诸侯也。凡为天下国家有九经，所以行之者一也。"]],note:"列九经之「目」（具体做法）：齐明盛服、非礼不动，所以修身；去谗远色、贱货贵德，所以劝贤；尊其位、重其禄、同其好恶，所以劝亲亲；官盛任使，所以劝大臣；忠信重禄，所以劝士；时使薄敛，所以劝百姓；日省月试、既禀称事（俸禄与事功相称），所以劝百工；送往迎来、嘉善而矜不能，所以柔远人；继绝世、举废国、治乱持危、朝聘以时、厚往而薄来，所以怀诸侯。末句「所以行之者一也」——一，即诚。"},{id:"yuzhe",label:"凡事豫则立 · 诚身有道 · 诚者天之道",showLabel:!0,sentences:[["凡事",{text:"豫",glossary:"yu"},"则立，不豫则废。言前定则不",{text:"跲",glossary:"jia"},"，事前定则不困，行前定则不",{text:"疚",glossary:"jiu"},"，道前定则不穷。在下位不获乎上，民不可得而治矣；获乎上有道：不信乎朋友，不获乎上矣；信乎朋友有道：不顺乎亲，不信乎朋友矣；顺乎亲有道：",{text:"反诸身不诚",glossary:"fanzhushen"},"，不顺乎亲矣；诚身有道：不明乎善，不诚乎身矣。"],["诚者，天之道也；诚之者，人之道也。诚者不勉而中，不思而得，",{text:"从容中道",glossary:"congrong"},"，圣人也。诚之者，",{text:"择善而固执之",glossary:"zeshan"},"者也。"]],note:"「凡事豫则立，不豫则废」：言前定则不跲（不绊跌），事前定则不困，行前定则不疚，道前定则不穷。又层层推求：「在下位不获乎上，民不可得而治矣」——获上有道，在于信乎朋友；信友有道，在于顺乎亲；顺亲有道，在于反诸身而诚；诚身有道，在于明乎善。末段立「诚」之二义：「诚者，天之道也」——不勉而中、不思而得、从容中道，是圣人；「诚之者，人之道也」——择善而固执之，是学者功夫。"},{id:"weixue",label:"博学审问慎思明辨笃行 · 人一能之己百之",showLabel:!0,sentences:[["博学之，审问之，慎思之，明辨之，笃行之。有弗学，学之弗能",{text:"弗措",glossary:"fucuo"},"也；有弗问，问之弗知弗措也；有弗思，思之弗得弗措也；有弗辨，辨之弗明弗措也；有弗行，行之弗笃弗措也；人一能之己百之，人十能之己千之。果能此道矣，虽愚必明，虽柔必强。"]],note:"为学之序五项：「博学之，审问之，慎思之，明辨之，笃行之」。又有五项「弗措」（不罢休）：有弗学，学之弗能弗措也……有弗行，行之弗笃弗措也。「人一能之，己百之；人十能之，己千之」——别人一遍能，自己就做百遍；别人十遍能，自己就做千遍。「果能此道矣，虽愚必明，虽柔必强。」"}],s=[{id:"fangce",term:"方策",pinyin:"fāng cè",meaning:"方：木板；策：竹简。布在方策，谓政事布列于典籍之上。"},{id:"minzheng",term:"敏政",pinyin:"mǐn zhèng",meaning:"敏：速。人道敏政、地道敏树——犹言人敏于政，地敏于树。"},{id:"pulu",term:"蒲卢",pinyin:"pú lú",meaning:"蒲苇，易生之物。一说为蜾蠃（细腰蜂）。喻政之易生。"},{id:"shai",term:"亲亲之杀",pinyin:"qīn qīn zhī shài",meaning:"杀：等差、降杀（读 shài）。亲亲有等差，尊贤有等级，礼由此而生。"},{id:"dadao",term:"达道",pinyin:"dá dào",meaning:"天下通行之道，共五者：君臣、父子、夫妇、昆弟、朋友之交。"},{id:"dade",term:"达德",pinyin:"dá dé",meaning:"天下通行之德，共三者：知、仁、勇。所以行之者一也——朱注谓「一」即诚。"},{id:"jiujing",term:"九经",pinyin:"jiǔ jīng",meaning:"为天下国家的九条常道：修身、尊贤、亲亲、敬大臣、体群臣、子庶民、来百工、柔远人、怀诸侯。"},{id:"xuan",term:"眩",pinyin:"xuàn",meaning:"迷惑。敬大臣则不眩——事有大臣任之，故不迷乱。"},{id:"quan",term:"劝",pinyin:"quàn",meaning:"勉励、鼓励。"},{id:"linchen",term:"既禀称事",pinyin:"jì lǐn chèn shì",meaning:"既：同「饩」（廪食）；禀：给。谓所给之食与其事相称。"},{id:"yu",term:"豫",pinyin:"yù",meaning:"预先。凡事豫则立，不豫则废。"},{id:"jia",term:"跲",pinyin:"jiá",meaning:"绊倒、窒碍。言前定则不跲——话先说定，就不会陷入窘境。"},{id:"jiu",term:"疚",pinyin:"jiù",meaning:"病、不安。行前定则不疚。"},{id:"fanzhushen",term:"反诸身不诚",pinyin:"fǎn zhū shēn bù chéng",meaning:"反求于自身而不真实无妄。"},{id:"congrong",term:"从容中道",pinyin:"cōng róng zhòng dào",meaning:"从容自然而合乎中道。中：读 zhòng（合）。"},{id:"zeshan",term:"择善而固执之",pinyin:"zé shàn ér gù zhí zhī",meaning:"选择善而坚定持守——朱注：「诚之者，择善而固执之者也。」即贤人由明而诚的功夫。"},{id:"fucuo",term:"弗措",pinyin:"fú cuò",meaning:"不放下、不罢休。学之弗能弗措——不学到会，绝不放下。"}];return(y,n)=>{const l=r("DaoTextReading"),t=r("DaoKeywordCards");return h(),d("div",null,[n[0]||(n[0]=i("h1",{id:"中庸·第20章",tabindex:"-1"},[e("中庸·第20章 "),i("a",{class:"header-anchor",href:"#中庸·第20章","aria-label":'Permalink to "中庸·第20章"'},"​")],-1)),n[1]||(n[1]=i("h2",{id:"【原典层】原文",tabindex:"-1"},[e("【原典层】原文 "),i("a",{class:"header-anchor",href:"#【原典层】原文","aria-label":'Permalink to "【原典层】原文"'},"​")],-1)),n[2]||(n[2]=i("p",null,[e("第二十章是全篇最长的一章（「哀公问政」）：由为政之道说起——"),i("strong",null,"为政在人，取人以身，修身以道，修道以仁"),e("；再列仁义礼三者的关系、五达道与三达德、九经；最后落到「"),i("strong",null,"诚"),e("」与为学五步。默认竹简沉浸通读；切「经典阅读」可点生词。")],-1)),a(l,{colophon:"为政在人 · 五达道三达德 · 九经 · 诚者天之道",tone:"ink",sections:o,glossary:s,"default-mode":"slips","aria-label":"中庸·第20章 原文"}),n[3]||(n[3]=i("h2",{id:"【原典层】注音与字词",tabindex:"-1"},[e("【原典层】注音与字词 "),i("a",{class:"header-anchor",href:"#【原典层】注音与字词","aria-label":'Permalink to "【原典层】注音与字词"'},"​")],-1)),a(t,{items:[{term:"方策",pinyin:["fāng","cè"],meaning:"方：木板；策：竹简。布在方策，谓政事布列于典籍。"},{term:"敏政",pinyin:["mǐn","zhèng"],meaning:"敏：速。人道敏政，犹言人敏于政。"},{term:"蒲卢",pinyin:["pú","lú"],meaning:"蒲苇，易生之物。喻政易生而速成。"},{term:"亲亲之杀",pinyin:["qīn","qīn","zhī","shài"],meaning:"杀：等差（读 shài）。亲亲有等差、尊贤有等级，礼由此生。"},{term:"达道",pinyin:["dá","dào"],meaning:"天下通行之道，有五：君臣、父子、夫妇、昆弟、朋友。"},{term:"达德",pinyin:["dá","dé"],meaning:"天下通行之德，有三：知、仁、勇。"}]}),a(t,{items:[{term:"九经",pinyin:["jiǔ","jīng"],meaning:"修身、尊贤、亲亲、敬大臣、体群臣、子庶民、来百工、柔远人、怀诸侯——为天下国家的九条常道。"},{term:"豫",pinyin:["yù"],meaning:"预先。凡事豫则立，不豫则废。"},{term:"择善而固执之",pinyin:["zé","shàn","ér","gù","zhí","zhī"],meaning:"择善而坚定持守——贤人「由明而诚」的功夫（朱注）。"},{term:"弗措",pinyin:["fú","cuò"],meaning:"不放下、不罢休。"},{term:"人一能之己百之",pinyin:["rén","yī","néng","zhī","jǐ","bǎi","zhī"],meaning:"别人一遍能，自己就做一百遍——困知勉行者的功夫。"}]}),n[4]||(n[4]=m("",31))])}}});export{b as __pageData,z as default};
